impl Specification {
    pub(super) fn add_eval_ir_bmem_core(&mut self) -> Result<(), SpecError> {
        let description =
            "ByteV1 core (designs/2026-10-01-evalir-bytev1-memory.md); generated by emit_core.py.";
        for (inductive, source) in decls() {
            if inductive {
                self.add_inductive(source, description)?;
            } else {
                self.add_recursive_def(source, description)?;
            }
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_bmem_core_sources_are_balanced_and_named_in_order() {
        let ds = decls();
        assert_eq!(ds.len(), BMEM_CORE_NAMES.len());
        for ((inductive, src), name) in ds.iter().zip(BMEM_CORE_NAMES) {
            assert_eq!(
                src.matches('(').count(),
                src.matches(')').count(),
                "{name}: unbalanced parentheses"
            );
            let head = if *inductive { "inductive" } else { "def" };
            assert!(src.starts_with(&format!("{head} {name} ")), "{name}");
        }
    }
}
